/* global CustomFunctions, AbortController */
import { arborAxiosLimiter } from "../http/limiter";
import { ArborScreenFailResult, ArborScreenResult } from "./types";
import { AxiosError } from "axios";
import { returnErrorEntity } from "./utils";
import { cellProvider, successCellIcon } from "../constants";
import { isVersionSupported } from "./utils";
import { getFromWorkbookSettings } from "../taskpane/taskpane";
/**
 * Screens stocks based on given criteria.
 * @customfunction ARBOR_SCREEN
 * @param {string} query The screening criteria
 * @param {CustomFunctions.CancelableInvocation} invocation Invocation object.
 * @returns {Promise<Excel.EntityCellValue | string>} An array of stock symbols that match the criteria
 * @cancellable
 * @requiresAddress
 * @helpurl https://docs.arborchat.ai/arborchat-for-excel/available-functions
 */
export async function screen(
  query: string,
  invocation: CustomFunctions.CancelableInvocation
): Promise<Excel.EntityCellValue | string> {
  const useNewScreener = (await getFromWorkbookSettings("useNewScreener")) === "true";
  const id = Math.random().toString(36).substring(2, 15);

  const diagnostic = Office.context.diagnostics;
  const isSupported = isVersionSupported(
    diagnostic.host as unknown as string,
    diagnostic.platform as unknown as string,
    diagnostic.version as unknown as string
  );
  const controller = new AbortController();

  invocation.onCanceled = () => {
    controller.abort();
  };

  if (!query.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Query is required");
  }

  try {
    const response = await arborAxiosLimiter.post(
      `/api/v1/screener/stock-suggestions`,
      { query },
      {
        signal: controller.signal, // @ts-ignore
        controller,
      }
    );
    if (response?.data?.error) {
      throw new AxiosError(response?.data?.error, response?.data?.error, response.config, response.request, response);
    }

    if (!useNewScreener && (!response?.data?.result || !response?.data?.result?.stocks?.length)) {
      throw new AxiosError(`NoResult`, "NoResult", response.config, response.request, response);
    }

    const stocksV2 = response.data.result?.stocksV2;
    const keys = Object.keys(stocksV2?.results?.[0] || {});

    const entity = {
      type: Excel.CellValueType.entity,
      text: `Screen: ${query}`,
      provider: cellProvider,
      properties: {
        success: {
          type: Excel.CellValueType.boolean,
          basicValue: true,
        },
        type: {
          type: Excel.CellValueType.string,
          basicValue: "ARBOR_SCREEN",
        },
        query: {
          type: Excel.CellValueType.string,
          basicValue: query,
        },
        ...(response.data.result.stocks.length > 0 && {
          answer: {
            type: Excel.CellValueType.array,
            elements: response.data.result.stocks.map((i) => [i.symbol, i.name]),
          },
        }),
        ...(useNewScreener && response.data.result.stocksV2
          ? {
              ...(keys.length > 0 && {
                answerV2: {
                  type: Excel.CellValueType.array,
                  elements: [
                    keys.map((k) => k || ""),
                    ...(stocksV2?.results?.map((i) => keys.map((k) => i[k] || "")) || keys.map(() => "")),
                  ],
                },
              }),
              answerV2OriginalSQLQuery: {
                type: Excel.CellValueType.string,
                basicValue: response.data.result.stocksV2?.originalSQLQuery || "",
              },
              answerV2SqlQuery: {
                type: Excel.CellValueType.string,
                basicValue: response.data.result.stocksV2?.sqlQuery || "",
              },
            }
          : {}),
        answeredAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].end.toISOString(),
        },
        queriedAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].start.toISOString(),
        },
        ...(response.data.result.references?.length > 0
          ? {
              references: {
                type: Excel.CellValueType.array,
                elements: response.data.result.references.map((ref) => {
                  if (ref.type === "private") {
                    return [
                      "private",
                      ref.fileId || "",
                      ref.page ? `page ${ref.page}` : "",
                      ref.label || "",
                      ref.value || "",
                    ];
                  } else {
                    return [
                      "internet",
                      ref.url || ("" as string),
                      ref.title || ("" as string),
                      ref.label || "",
                      ref.value || "",
                    ];
                  }
                }),
              },
            }
          : {}),
      },
      layouts: {
        compact: {
          icon: successCellIcon,
        },
      },
    } as ArborScreenResult;
    console.log({
      logType: "request",
      id,
      type: "ARBOR_SCREEN",
      query,
      options: {},
      entity,
      response: response?.data,
      address: invocation.address,
      start: response.config["metadata"].start.toISOString(),
      end: response.config["metadata"].end.toISOString(),
    });
    if (!isSupported) {
      return response.data.result.map((i) => i.symbol).join("\n");
    }
    return entity;
  } catch (error: any | AxiosError) {
    const errorEntity = returnErrorEntity<ArborScreenFailResult>(error, {
      type: {
        type: Excel.CellValueType.string,
        basicValue: "ARBOR_SCREEN",
      },
      query: {
        type: Excel.CellValueType.string,
        basicValue: query || "",
      },
    });

    console.log({
      logType: "request",
      id,
      type: "ARBOR_SCREEN",
      query,
      options: {},
      entity: errorEntity,
      error: error,
      address: invocation.address,
      response: error.response?.data,
      start: error?.config["metadata"]?.start?.toISOString(),
      end: error?.config["metadata"]?.end?.toISOString(),
    });
    if (!isSupported) {
      return errorEntity.text;
    }
    return errorEntity;
  }
}

CustomFunctions.associate("ARBOR_SCREEN", screen);