/* global CustomFunctions, AbortController */

import { arborAxiosLimiter } from "../http/limiter";
import { AxiosError } from "axios";
import { isVersionSupported, returnErrorEntity } from "./utils";
import { cellProvider, successCellIcon } from "../constants";

const recursiveJoin = (args: any): string => {
  if (typeof args === "string") {
    return args;
  }
  if (Array.isArray(args)) {
    return args.map(recursiveJoin).join(" ");
  }
  if (typeof args === "object") {
    return Object.values(args).map(recursiveJoin).join(" ");
  }
  return "";
};

/**
 * Returns a list of answers from GPT.
 * @customfunction ARBOR_GPT_LIST
 * @param {string[][]} query The question to ask about a list of items
 * @param {CustomFunctions.CancelableInvocation} invocation Invocation object.
 * @returns {Promise<Excel.EntityCellValue | string>} The list of answers from GPT
 * @cancellable
 * @helpurl https://docs.arborchat.ai/arborchat-for-excel/available-functions
 */
export async function arborGptList(...args: string[][][]): Promise<Excel.EntityCellValue | string> {
  const id = Math.random().toString(36).substring(2, 15);

  console.log("ARBOR_GPT_LIST", args);
  const diagnostic = Office.context.diagnostics;
  const isSupported = isVersionSupported(
    diagnostic.host as unknown as string,
    diagnostic.platform as unknown as string,
    diagnostic.version as unknown as string
  );

  const invocation = args.pop() as CustomFunctions.CancelableInvocation;
  const controller = new AbortController();

  invocation.onCanceled = () => {
    controller.abort();
  };

  const queryString = recursiveJoin(args);

  if (!queryString.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Query is required");
  }

  try {
    const response = await arborAxiosLimiter.post(
      `/api/v1/screener/gpt-list`,
      {
        query: queryString,
      },
      {
        signal: controller.signal,
        // @ts-ignore
        controller,
      }
    );

    if (response.data?.error) {
      throw new AxiosError(
        response.data.error,
        response.status.toString(),
        response.config,
        response.request,
        response
      );
    }

    if (!response.data?.result || !Array.isArray(response.data.result)) {
      throw new AxiosError("FailToAnswer", response.status.toString(), response.config, response.request, response);
    }

    const entity: Excel.EntityCellValue = {
      type: Excel.CellValueType.entity,
      text: `List: ${queryString}`,
      provider: cellProvider,
      properties: {
        type: {
          type: Excel.CellValueType.string,
          basicValue: "ARBOR_GPT_LIST",
        },
        success: {
          type: Excel.CellValueType.boolean,
          basicValue: true,
        },
        query: {
          type: Excel.CellValueType.string,
          basicValue: queryString,
        },
        answer: {
          type: Excel.CellValueType.array,
          elements: response.data.result.map((str: string) => [str]),
        },
        answeredAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].end.toISOString(),
        },
        queriedAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].start.toISOString(),
        },
      },
      layouts: {
        compact: {
          icon: successCellIcon,
        },
      },
    };
    console.log({
      logType: "request",
      id,
      type: "ARBOR_GPT_LIST",
      query: queryString,
      options: {},
      entity,
      address: invocation.address,
      response: response?.data,
      start: response.config["metadata"].start.toISOString(),
      end: response.config["metadata"].end.toISOString(),
    });
    if (!isSupported) {
      return response.data.result.join("\n");
    }
    return entity;
  } catch (error) {
    const errorEntity = returnErrorEntity(error, {
      type: {
        type: Excel.CellValueType.string,
        basicValue: "ARBOR_GPT_LIST",
      },
      success: {
        type: Excel.CellValueType.boolean,
        basicValue: false,
      },
      query: {
        type: Excel.CellValueType.string,
        basicValue: queryString,
      },
    });
    console.log({
      logType: "request",
      id,
      type: "ARBOR_GPT_LIST",
      query: queryString,
      options: {},
      entity: errorEntity,
      error: error,
      address: invocation.address,
      response: error.response?.data,
      start: error?.config["metadata"]?.start?.toISOString(),
      end: error?.config["metadata"]?.end?.toISOString(),
    });
    if (!isSupported) {
      return errorEntity.text;
    }
    return errorEntity;
  }
}

CustomFunctions.associate("ARBOR_GPT_LIST", arborGptList);