/* global CustomFunctions, AbortController */

import { arborAxiosLimiter } from "../http/limiter";
import { ArborNumberFailResult, ArborNumberSuccessResult } from "./types";
import { cellProvider, successCellIcon } from "../constants";
import { returnErrorEntity } from "./utils";
import { AxiosError } from "axios";
import { isVersionSupported } from "./utils";
import { getFromWorkbookSettings } from "../taskpane/taskpane";

/**
 * Answers questions about a company based on its stock symbol in a short format.
 * @customfunction ARBOR_NUMBER
 * @param {string} ticker The stock symbol of the company
 * @param {string} query The question to ask about the company
 * @param {string} [knowledgeSpace] The knowledge space to use options: 'internet', 'private', 'hybrid', default is 'internet'
 * @param {string[][]} [privateFileFiltering] The private file filtering to use, format: [["id:123", "label1"], ["id:456", "label2"]]
 * @param {CustomFunctions.CancelableInvocation} invocation Invocation object.
 * @returns {Promise<Excel.EntityCellValue | string>} The answer to the query
 * @cancellable
 * @requiresAddress
 * @helpurl https://docs.arborchat.ai/arborchat-for-excel/available-functions
 */
export async function answerNumber(
  ticker: string,
  query: string,
  knowledgeSpace: string,
  privateFileFiltering: string[][],
  invocation: CustomFunctions.CancelableInvocation
): Promise<Excel.EntityCellValue | string> {
  const id = Math.random().toString(36).substring(2, 15);
  console.log("ARBOR_NUMBER", ticker, query, knowledgeSpace, privateFileFiltering);
  // backward compatibility

  if (knowledgeSpace && knowledgeSpace["functionName"]) {
    invocation = knowledgeSpace as unknown as CustomFunctions.CancelableInvocation;
    knowledgeSpace = undefined;
    privateFileFiltering = undefined;
  }

  if (privateFileFiltering && privateFileFiltering["functionName"]) {
    invocation = privateFileFiltering as unknown as CustomFunctions.CancelableInvocation;
    privateFileFiltering = undefined;
  }

  const diagnostic = Office.context.diagnostics;
  const isSupported = isVersionSupported(
    diagnostic.host as unknown as string,
    diagnostic.platform as unknown as string,
    diagnostic.version as unknown as string
  );

  const controller = new AbortController();

  invocation.onCanceled = () => {
    controller.abort();
  };

  if (!query.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Query is required");
  }
  if (!ticker.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Ticker is required");
  }
  if (knowledgeSpace && !["internet", "hybrid", "private"].includes(knowledgeSpace)) {
    throw new CustomFunctions.Error(
      CustomFunctions.ErrorCode.invalidValue,
      "Knowledge space is invalid, options: 'internet', 'hybrid', 'private'"
    );
  }

  const fileIds = [];
  const labels = [];
  (privateFileFiltering || []).forEach((array) => {
    array
      .filter((str) => str.toString().trim().length > 0)
      .forEach((str) => {
        if (str.startsWith("id:")) {
          fileIds.push(str.split(":")[1]);
        } else {
          labels.push(str);
        }
      });
  });
  try {
    const provider = await getFromWorkbookSettings("modelProvider");

    const response = await arborAxiosLimiter.post(
      `/api/v1/answer-number`,
      {
        query: query,
        stockSymbol: ticker,
        forceAnswer: true,
        hidePromoText: true,
        provider: provider || "openai",
        knowledgeSpace: knowledgeSpace || "internet",
        privateDocument: {
          fileIds,
          labels,
        },
      },
      {
        signal: controller.signal,
        // @ts-ignore
        controller,
      }
    );

    if (response.data?.result?.answer == undefined || response.data?.result?.answer == null) {
      throw new AxiosError("FailToAnswer", response.status.toString(), response.config, response.request, response);
    }

    console.log("response", response.data);

    const entity: ArborNumberSuccessResult = {
      type: Excel.CellValueType.entity,
      text: `${response.data.result.answer}`,
      provider: cellProvider,
      properties: {
        type: {
          type: Excel.CellValueType.string,
          basicValue: "ARBOR_NUMBER",
        },
        success: {
          type: Excel.CellValueType.boolean,
          basicValue: true,
        },
        ticker: {
          type: Excel.CellValueType.string,
          basicValue: ticker,
        },
        query: {
          type: Excel.CellValueType.string,
          basicValue: query || "",
        },
        knowledgeSpace: {
          type: Excel.CellValueType.string,
          basicValue: knowledgeSpace || "internet",
        },
        answer: {
          type: Excel.CellValueType.double,
          basicValue: parseFloat(response.data.result.answer) || 0,
        },
        reason: {
          type: Excel.CellValueType.string,
          basicValue: response.data.result.reason || response.data.result.answerExplanation || "",
        },
        answeredAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].end.toISOString(),
        },
        queriedAt: {
          type: Excel.CellValueType.string,
          basicValue: response.config["metadata"].start.toISOString(),
        },
        ...(response.data.result.references?.length > 0
          ? {
              references: {
                type: Excel.CellValueType.array,
                elements: response.data.result.references.map((ref) => {
                  if (ref.type === "private") {
                    return [
                      "private",
                      ref.fileId || "",
                      ref.page ? `page ${ref.page}` : "",
                      ref.label || "",
                      ref.value || "",
                    ];
                  } else {
                    return [
                      "internet",
                      ref.url || ("" as string),
                      ref.title || ("" as string),
                      ref.label || "",
                      ref.value || "",
                    ];
                  }
                }),
              },
            }
          : {}),
        ...(fileIds?.length > 0 || labels?.length > 0
          ? {
              privateFileFiltering: {
                type: Excel.CellValueType.array,
                elements: privateFileFiltering.map((array) =>
                  array.map((str) => ({ type: Excel.CellValueType.string, basicValue: str || "" }))
                ),
              },
            }
          : {}),
      },
      layouts: {
        compact: {
          icon: successCellIcon,
        },
      },
    };
    console.log({
      logType: "request",
      id,
      type: "ARBOR_NUMBER",
      ticker,
      query,
      options: {},
      entity,
      address: invocation.address,
      response: response?.data,
      start: response.config["metadata"].start.toISOString(),
      end: response.config["metadata"].end.toISOString(),
    });
    if (!isSupported) {
      return entity.text;
    }
    return entity;
  } catch (error: any | AxiosError) {
    const errorEntity = returnErrorEntity<ArborNumberFailResult>(error, {
      type: {
        type: Excel.CellValueType.string,
        basicValue: "ARBOR_NUMBER",
      },
      ticker: {
        type: Excel.CellValueType.string,
        basicValue: ticker,
      },
      query: {
        type: Excel.CellValueType.string,
        basicValue: query || "",
      },
      knowledgeSpace: {
        type: Excel.CellValueType.string,
        basicValue: knowledgeSpace || "internet",
      },
      ...(fileIds?.length > 0 || labels?.length > 0
        ? {
            privateFileFiltering: {
              type: Excel.CellValueType.array,
              elements: privateFileFiltering.map((array) =>
                array.map((str) => ({ type: Excel.CellValueType.string, basicValue: str || "" }))
              ),
            },
          }
        : {}),
    });
    console.log({
      logType: "request",
      id,
      type: "ARBOR_NUMBER",
      ticker,
      query,
      options: {},
      entity: errorEntity,
      error: error,
      address: invocation.address,
      response: error.response?.data,
      start: error?.config["metadata"]?.start?.toISOString(),
      end: error?.config["metadata"]?.end?.toISOString(),
    });
    if (!isSupported) {
      return errorEntity.text;
    }
    return errorEntity;
  }
}

CustomFunctions.associate("ARBOR_NUMBER", answerNumber);